import { Controller, Get, Post, Put, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isNum(v: unknown): boolean {
  if (typeof v === 'number') return Number.isFinite(v);
  if (typeof v === 'string') return v.trim() !== '' && Number.isFinite(Number(v));
  return false;
}

function gradeInput(data: Record<string, unknown>) {
  const gradeGroup = typeof data['gradeGroup'] === 'string' ? data['gradeGroup'].trim() : '';
  if (gradeGroup === '' || gradeGroup.length > 100) {
    throw new ApiError(400, 'VALIDATION_FAILED', '직급/직군을 100자 이내로 입력하세요.');
  }
  if (!isNum(data['step']) || !Number.isInteger(Number(data['step'])) || Number(data['step']) <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '호봉은 1 이상의 정수로 입력하세요.');
  }
  if (!isNum(data['amount']) || Number(data['amount']) < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '호봉별 금액은 0 이상의 숫자로 입력하세요.');
  }
  const raw = data['effectiveFrom'];
  let effectiveFrom: string | null = null;
  if (raw !== undefined && raw !== null && raw !== '') {
    if (typeof raw !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일은 YYYY-MM-DD 형식으로 입력하세요.');
    }
    effectiveFrom = raw;
  }
  return {
    gradeGroup,
    step: String(Number(data['step'])),
    amount: String(Number(data['amount'])),
    effectiveFrom,
  };
}

function idOf(value: unknown, label: string): string {
  const text = typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '';
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr02107Controller {
  @Post('/salary-grade-tables')
  @HttpCode(200)
  async createSalaryGradeTable(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const input = gradeInput(data);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE grade_group = :gradeGroup AND step = CAST(:step AS integer)',
        { gradeGroup: input.gradeGroup, step: input.step },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SALARY_GRADE_DUPLICATED', '동일 직급/직군에 같은 호봉이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO salary_grade_table (grade_group, step, amount, effective_from, created_at, updated_at) ' +
          'VALUES (:gradeGroup, CAST(:step AS integer), CAST(:amount AS numeric), CAST(:effectiveFrom AS date), now(), now()) ' +
          'RETURNING salary_grade_table_id AS "salaryGradeTableId"',
        input,
      );
      return rows[0];
    });
  }

  @Put('/salary-grade-tables/:salaryGradeTableId')
  async updateSalaryGradeTable(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['salaryGradeTableId'], '호봉테이블 ID');
    const data = checks.inputOf(req.body);
    const input = gradeInput(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE salary_grade_table_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SALARY_GRADE_NOT_FOUND', '호봉테이블 항목을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table ' +
          'WHERE grade_group = :gradeGroup AND step = CAST(:step AS integer) AND salary_grade_table_id <> CAST(:id AS bigint)',
        { gradeGroup: input.gradeGroup, step: input.step, id },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'SALARY_GRADE_DUPLICATED', '수정 결과가 기존 호봉과 중복됩니다.');
      }
      const rows = await db.query(
        'UPDATE salary_grade_table SET grade_group = :gradeGroup, step = CAST(:step AS integer), ' +
          'amount = CAST(:amount AS numeric), effective_from = CAST(:effectiveFrom AS date), updated_at = now() ' +
          'WHERE salary_grade_table_id = CAST(:id AS bigint) RETURNING salary_grade_table_id AS "salaryGradeTableId"',
        { ...input, id },
      );
      return rows[0];
    });
  }

  @Get('/salary-grade-tables')
  async listSalaryGradeTables(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    let page = Number(query['page'] ?? 0);
    let size = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상의 정수여야 합니다.');
    }
    if (size > MAX_SIZE) size = MAX_SIZE;
    const gradeGroup = typeof query['gradeGroup'] === 'string' ? query['gradeGroup'].trim() : '';
    return transaction(async (db) => {
      const params = { gradeGroup, size, offset: page * size };
      const where = '(:gradeGroup = \'\' OR grade_group = :gradeGroup)';
      const items = await db.query(
        'SELECT salary_grade_table_id AS "salaryGradeTableId", grade_group AS "gradeGroup", step AS "step", ' +
          'amount AS "amount", effective_from AS "effectiveFrom" FROM salary_grade_table WHERE ' +
          where +
          ' ORDER BY grade_group, step LIMIT :size OFFSET :offset',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM salary_grade_table WHERE ' + where,
        { gradeGroup },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Patch('/employee-salaries/:employeeSalaryId/grade')
  async assignEmployeeSalaryGrade(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['employeeSalaryId'], '임직원 책정임금 ID');
    const data = checks.inputOf(req.body);
    const gradeId = idOf(data['salaryGradeTableId'], '호봉테이블 ID');
    return transaction(async (db) => {
      const salary = await db.query(
        'SELECT employee_salary_id FROM employee_salary WHERE employee_salary_id = CAST(:id AS bigint)',
        { id },
      );
      if (salary.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_SALARY_NOT_FOUND', '임직원 책정임금 정보를 찾을 수 없습니다.');
      }
      const grade = await db.query(
        'SELECT salary_grade_table_id FROM salary_grade_table WHERE salary_grade_table_id = CAST(:gradeId AS bigint)',
        { gradeId },
      );
      if (grade.length === 0) {
        throw new ApiError(404, 'SALARY_GRADE_NOT_FOUND', '지정한 호봉을 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE employee_salary SET salary_grade_table_id = CAST(:gradeId AS bigint), updated_at = now() ' +
          'WHERE employee_salary_id = CAST(:id AS bigint) ' +
          'RETURNING employee_salary_id AS "employeeSalaryId", salary_grade_table_id AS "salaryGradeTableId"',
        { id, gradeId },
      );
      return rows[0];
    });
  }
}

