import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Panel =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'assign'; row: Row }
  | null;

export default function FnSfr02107Page({ role, notify }: PageProps) {
  const [gradeGroup, setGradeGroup] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [salaryPage, setSalaryPage] = useState(0);
  const [panel, setPanel] = useState<Panel>(null);

  const [fGroup, setFGroup] = useState<unknown>('');
  const [fStep, setFStep] = useState<unknown>('');
  const [fAmount, setFAmount] = useState<unknown>('');
  const [fFrom, setFFrom] = useState<unknown>('');
  const [fGrade, setFGrade] = useState<unknown>('');

  const grades = useData<Page>(
    () => call<Page>('GET', '/salary-grade-tables', role, undefined, { gradeGroup, page, size: 20 }),
    [gradeGroup, page, role],
  );
  const salaries = useData<Page>(
    () => call<Page>('GET', '/employee-salaries', role, undefined, { appliedFrom: applied, page: salaryPage, size: 20 }),
    [applied, salaryPage, role],
  );

  const openCreate = () => {
    setFGroup('');
    setFStep('');
    setFAmount('');
    setFFrom('');
    setPanel({ kind: 'create' });
  };

  const openEdit = (row: Row) => {
    setFGroup(row['gradeGroup'] ?? '');
    setFStep(row['step'] ?? '');
    setFAmount(row['amount'] ?? '');
    setFFrom(row['effectiveFrom'] ?? '');
    setPanel({ kind: 'edit', row });
  };

  const openAssign = (row: Row) => {
    setFGrade(row['salaryGradeTableId'] ?? '');
    setPanel({ kind: 'assign', row });
  };

  const submitGrade = async () => {
    if (String(fGroup ?? '').trim() === '') throw new Error('직급/직군을 입력하세요.');
    if (fStep === '' || fStep === null || fStep === undefined) throw new Error('호봉을 입력하세요.');
    if (fAmount === '' || fAmount === null || fAmount === undefined) throw new Error('호봉별 금액을 입력하세요.');
    const body: Row = {
      gradeGroup: fGroup,
      step: fStep,
      amount: fAmount,
      effectiveFrom: fFrom === '' ? null : fFrom,
    };
    if (panel && panel.kind === 'edit') {
      await call('PUT', '/salary-grade-tables/' + String(panel.row['salaryGradeTableId']), role, body);
      notify('호봉테이블을 수정했습니다.');
    } else {
      await call('POST', '/salary-grade-tables', role, body);
      notify('호봉테이블을 등록했습니다.');
    }
    setPanel(null);
    grades.reload();
  };

  const submitAssign = async () => {
    if (!panel || panel.kind !== 'assign') return;
    if (fGrade === '' || fGrade === null || fGrade === undefined) throw new Error('호봉테이블을 선택하세요.');
    await call(
      'PATCH',
      '/employee-salaries/' + String(panel.row['employeeSalaryId']) + '/grade',
      role,
      { salaryGradeTableId: fGrade },
    );
    notify('임직원 호봉을 지정했습니다.');
    setPanel(null);
    salaries.reload();
  };

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>호봉테이블</h2>
        <Filters
          onSearch={() => setPage(0)}
          onReset={() => {
            setGradeGroup('');
            setPage(0);
          }}
        >
          <Field label="직급/직군">
            <TextInput value={gradeGroup} onChange={setGradeGroup} />
          </Field>
        </Filters>
        <Band total={grades.data?.total}>
          <button onClick={openCreate}>호봉 등록</button>
        </Band>
        {grades.error && <ErrorText text={grades.error} />}
        <DataTable
          rows={grades.data?.items ?? []}
          empty="등록된 호봉이 없습니다."
          columns={[
            { key: 'gradeGroup', label: '직급/직군' },
            { key: 'step', label: '호봉' },
            { key: 'amount', label: '호봉별 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'effectiveFrom', label: '적용 시작일', render: (r) => <DateText value={r['effectiveFrom']} /> },
            {
              key: 'edit',
              label: '관리',
              render: (r) => <button onClick={() => openEdit(r)}>수정</button>,
            },
          ]}
        />
        <Pager
          page={grades.data?.page ?? 0}
          size={grades.data?.size ?? 20}
          total={grades.data?.total ?? 0}
          onPage={setPage}
        />
      </section>
      <section className="box span-4">
        <h2>호봉 현황</h2>
        <Band total={salaries.data?.total} />
        <p>임직원 책정임금 목록에서 호봉을 지정합니다.</p>
      </section>
      <section className="box span-12">
        <h2>임직원 책정임금</h2>
        <Filters
          onSearch={() => setSalaryPage(0)}
          onReset={() => {
            setApplied('');
            setSalaryPage(0);
          }}
        >
          <Field label="적용 시작일">
            <DateInput value={applied} onChange={setApplied} />
          </Field>
        </Filters>
        {salaries.error && <ErrorText text={salaries.error} />}
        <DataTable
          rows={salaries.data?.items ?? []}
          empty="조회된 책정임금이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'assignedSalary', label: '책정임금', render: (r) => <Num value={r['assignedSalary']} /> },
            { key: 'appliedFrom', label: '적용 시작일', render: (r) => <DateText value={r['appliedFrom']} /> },
            { key: 'changeReason', label: '변경 사유' },
            { key: 'updatedAt', label: '수정 일시', render: (r) => <DateText value={r['updatedAt']} time /> },
            {
              key: 'assign',
              label: '호봉',
              render: (r) => <button onClick={() => openAssign(r)}>호봉 지정</button>,
            },
          ]}
        />
        <Pager
          page={salaries.data?.page ?? 0}
          size={salaries.data?.size ?? 20}
          total={salaries.data?.total ?? 0}
          onPage={setSalaryPage}
        />
      </section>
      {panel && (panel.kind === 'create' || panel.kind === 'edit') && (
        <Drawer title={panel.kind === 'create' ? '호봉 등록' : '호봉 수정'} onClose={() => setPanel(null)}>
          <Form onSubmit={submitGrade} submit={panel.kind === 'create' ? '등록' : '수정'}>
            <Field label="직급/직군" required>
              <TextInput value={fGroup} onChange={setFGroup} />
            </Field>
            <Field label="호봉" required>
              <NumberInput value={fStep} onChange={setFStep} />
            </Field>
            <Field label="호봉별 금액" required>
              <NumberInput value={fAmount} onChange={setFAmount} />
            </Field>
            <Field label="적용 시작일">
              <DateInput value={fFrom} onChange={setFFrom} />
            </Field>
          </Form>
        </Drawer>
      )}
      {panel && panel.kind === 'assign' && (
        <Drawer title="임직원 호봉 지정" onClose={() => setPanel(null)}>
          <Form onSubmit={submitAssign} submit="지정">
            <Field label="임직원">
              <RefName table="employee" role={role} value={panel.row['employeeId']} />
            </Field>
            <Field label="호봉테이블 ID" required>
              <LookupSelect table="salary_grade_table" role={role} value={fGrade} onChange={setFGrade} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
